'use strict';
const BAKERY_UI5={bind,menuView,financeView,help,performanceDetail5,performanceView};
TITLES.bakery='Jídlo & vlastní pekárna';
let foodStore5=null,selectedBakery5=null,selectedFoodRecipe5='food-croissant';
function bakeryView(){const stores=state.stores.filter(s=>!s.franchise),bs=state.bakery5.bakeries;if(!stores.some(s=>s.id===foodStore5))foodStore5=stores[0]?.id||null;if(!bs.some(b=>b.id===selectedBakery5))selectedBakery5=bs[0]?.id||null;if(!state.bakery5.recipes.some(r=>r.id===selectedFoodRecipe5))selectedFoodRecipe5=state.bakery5.recipes[0].id;const s=stores.find(s=>s.id===foodStore5),f=s?.food5,b=bakeryById5(selectedBakery5),r=foodRecipe5(selectedFoodRecipe5),h=state.bakery5.history.at(-1);return `<div class="view-toolbar"><p class="intro">Od receptury po vitrínu. Šest provozních dnů, čerstvý rozvoz a skutečné zásoby. Neprodané jídlo se zkazí; v neděli je zavřeno.</p><div class="actions"><button class="soft" data-food-report5="food">Report jídla</button><button class="soft" data-food-report5="bakeries">Report pekáren</button><button class="soft" id="foodForecast5" ${!stores.length?'disabled':''}>Výhled 4 týdnů</button></div></div><div class="report-overview5">${metric('VLASTNÍ PEKÁRNY',bs.length+' / 8','Výrobní tým má vlastní mzdy')}${metric('TRŽBY Z JÍDLA',h?money(h.revenue):'—','Skutečný prodej v kavárnách')}${metric('ODPIS ZÁSOB',h?money(h.waste):'—','Jídlo i suroviny po trvanlivosti')}${metric('NÁKUPY DO ZÁSOB',h?money(h.purchases):'—','Platby během posledního tahu')}</div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Vitrína a denní odběr kavárny</h2>${s?`<select id="foodStore5" aria-label="Kavárna pro jídlo">${stores.map(x=>option(x.id,loc(x.id).city+' · '+loc(x.id).name,s.id)).join('')}</select>`:''}</div>${s?`<div class="fields">${field('Zdroj denního rozvozu',`<select id="foodSource5">${option('external','Externí pekárna · každé ráno',f.source)}${bs.map(b=>option(b.id,b.name+(b.city===loc(s.id).city?' · čerstvé ráno':' · expres +1 den'),f.source)).join('')}</select>`)}${field('Limit nákupů / týden',input('foodBudget5',f.budget,0,100000,500))}${field('Chráněná rezerva / týdny',input('foodReserve5',f.reserve,1,8,1))}</div><div class="food-plan-grid5">${['pastry','sandwich'].map(cat=>{const p=f.plan[cat],rec=foodRecipe5(p.recipe),missing=!s.equipment[MENU[cat].requires];return `<div class="food-plan-card5"><span class="eyelabel">${cat==='pastry'?'PEČIVO A DEZERTY':'SENDVIČE'}</span>${field('Vlastní receptura',`<select id="foodRecipe-${cat}5">${state.bakery5.recipes.filter(x=>FOOD_BASES5[x.base].category===cat).map(x=>option(x.id,x.name,p.recipe)).join('')}</select>`)}${field('Rozvoz kusů každý den',input('foodQty-'+cat+'5',p.qty,0,500,5))}<p class="sub">${rec.life} ${rec.life===1?'den':'dny'} trvanlivosti · ${money(rec.unitCost)} / kus při výrobě, bez mezd a dopravy.</p><label class="checkbox-line"><input type="checkbox" data-food-menu5="${cat}" ${s.menu[cat].enabled?'checked':''} ${missing?'disabled':''}> Nabízet jídlo v menu</label>${field('Prodejní cena / kus',`<input type="number" min="35" max="350" value="${s.menu[cat].price}" data-food-price5="${cat}" aria-label="Cena ${MENU[cat].name}">`)}${missing?'<p class="bad">Pořiď '+esc(EQUIPMENT[MENU[cat].requires].name)+' v Menu & vybavení.</p>':''}</div>`;}).join('')}</div><label class="checkbox-line"><input type="checkbox" id="foodEnabled5" ${f.enabled?'checked':''}> Použít fyzické zásoby a tento denní plán</label><div class="actions"><button class="primary" id="foodPlanSave5">Uložit odběr jídla</button><button class="soft" data-goto="menu">Vybavit kavárnu</button></div><p class="sub">Při zapnutí se prodají pouze dostupné, čerstvé kusy, které hosté chtějí. Cena a receptura ovlivňují jejich zájem. Bez zapnutí platí dosavadní zjednodušený nákup jídla podle menu. Externí odběr hradí rozpočet kavárny; vlastní výrobu, suroviny i rozvoz hradí mandát pekárny. Mimo město trvá expres jeden den a stojí 7,50 Kč/kus; jednodenní pečivo a sendviče touto trasou nelze dodat čerstvé. Stejné město stojí 1,40 Kč/kus.</p>${f.last?.enabled?rows([['Prodané kusy',f.last.sold],['Nedostupné jídlo',f.last.lost+' požadovaných kusů'],['Tržby',money(f.last.revenue)],['Spotřebované zásoby',money(f.last.cost)],['Odpad',f.last.wasted+' ks · '+money(f.last.waste)],['Příspěvek před obsluhou a týmem pekárny',money(f.last.revenue-f.last.cost-f.last.waste)]]):empty('Po zapnutí fyzického odběru a odehraném týdnu uvidíš skutečný prodej.')}<details><summary>Šarže ve vitríně · ${foodStock5(s)} kusů</summary>${f.lots.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Receptura / verze</th><th>Kusů</th><th>Cena zásoby</th><th>Vyrobeno / dorazí / vyřadit</th></tr></thead><tbody>${f.lots.map(l=>`<tr><td>${esc(l.name)} · v${l.version}</td><td>${l.qty}</td><td>${money(l.cost)}/ks</td><td>${foodDayLabel5(l.made)} / ${foodDayLabel5(l.arrival)} / ${foodDayLabel5(l.expires)}</td></tr>`).join('')}</tbody></table></div>`:empty('Vitrína je prázdná.')}</details><details><summary>Poslední skutečný týden po dnech</summary>${f.last?.enabled?`<div class="table-scroll"><table class="data"><thead><tr><th>Den</th><th>Hosté</th><th>Jídlo</th><th>Chybělo</th><th>Tržby jídla</th></tr></thead><tbody>${f.last.days.map(x=>`<tr><td>${['Po','Út','St','Čt','Pá','So'][x.day]}</td><td>${x.served}</td><td>${x.sold}</td><td>${x.lost}</td><td>${money(x.revenue)}</td></tr>`).join('')}</tbody></table></div>`:empty('Ještě bez odehraného fyzického odběru.')}</details>`:empty('Otevři první vlastní kavárnu. Pak můžeš začít s externím pečivem a postupně pořídit pekárnu.')}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Vlastní výroba a tým</h2>${bs.length?`<select id="bakerySelect5" aria-label="Pekárna">${bs.map(x=>option(x.id,x.name,b?.id)).join('')}</select>`:''}</div>${b?`<div class="fields">${field('Pekaři (nábor 8 000 Kč / člověk)',input('bakeryStaff5',b.staff,1,15,1))}${field('Výrobní směny / den',`<select id="bakeryShifts5">${[1,2,3].map(n=>option(n,n+' směna / směny',b.shifts)).join('')}</select>`)}${field('Suroviny, energie a rozvoz / týden',input('bakeryBudget5',b.budget,0,200000,1000))}${field('Chráněná rezerva / týdny',input('bakeryReserve5',b.reserve,1,8,1))}</div><label class="checkbox-line"><input type="checkbox" id="bakeryAuto5" ${b.auto?'checked':''}> Denně automaticky dokoupit chybějící suroviny v mandátu</label><label class="checkbox-line"><input type="checkbox" id="bakeryMaintenance5" ${b.maintenance?'checked':''}> Automaticky servisovat pod 75 % ve stejném mandátu</label><div class="actions"><button class="primary" id="bakerySave5">Uložit provoz pekárny</button><button class="soft" id="bakeryService5">Servis · ${money(b.cost*.04)}</button></div>${rows([['Kapacita / den',bakeryCapacity5(b)+' pracovních jednotek'],['Stav zařízení',number(b.condition,1)+' / 100'],['Fixní tým a provoz / týden',money(bakeryFixed5(b))],['Vedoucí',esc(b.manager?.name||'Přímé řízení zakladatelem')]])}<p class="sub">Receptura spotřebuje vlastní počet pracovních jednotek. Více směn zvyšuje kapacitu a opotřebení; tým má pevné týdenní mzdy. Výroba následuje denní odběry, nejdřív v pořadí otevření kaváren. Suroviny se spotřebují podle nejbližšího konce trvanlivosti. Při nedostatku peněz, týmu nebo surovin se vyrobí méně; nevyužitá kapacita nevytváří zboží.</p><div class="actions">${state.talents.slice(0,3).map(p=>`<button class="soft" data-bakery-hire5="${p.pid}">${esc(p.name)} · mzda ${money(p.salary)}/t.</button>`).join('')}${b.manager?'<button class="quiet" id="bakeryFire5">Odvolat vedoucího</button>':''}<button class="soft" data-goto="people">Kariéry a školení</button></div><p class="sub">Nábor vedoucího ${money(Math.max(4000,12000-state.departments.hr*1500))}; jeho výrobní a provozní dovednosti ovlivní kvalitu i kapacitu.</p><h3 style="margin-top:20px">Sklad surovin</h3><div class="fields">${field('Surovina',`<select id="foodRawIngredient5">${Object.entries(INGREDIENTS5).map(([id,x])=>option(id,x.name+' · '+money(x.price)+'/kg · '+x.life+' dnů')).join('')}</select>`)}${field('Množství / kg',input('foodRawKg5',10,.1,500,.1))}</div><button class="soft" id="foodRawBuy5">Nakoupit surovinu ručně</button>${rows(Object.entries(INGREDIENTS5).map(([k,x])=>[x.name,number(b.raw.filter(l=>l.ingredient===k).reduce((n,l)=>n+l.kg,0),2)+' kg']))}${b.last?`<h3 style="margin-top:20px">Výsledek výrobního řetězce · T${b.last.week}</h3>${rows([['Vyrobeno / odesláno / prodáno',b.last.produced+' / '+b.last.delivered+' / '+b.last.sold+' kusů'],['Koncové tržby jídla',money(b.last.revenue)],['Spotřebovaná zásoba',money(b.last.cogs)],['Tým a provoz',money(b.last.operating)],['Odpis jídla a surovin',money(b.last.waste)],['Příspěvek řetězce před obsluhou kaváren',money(b.last.profit)],['Využití kapacity',number(b.last.utilization*100,1)+' %']])}`:empty('Pekárna začne vyrábět po nastavení odběrů a odehrání týdne.')}`:empty('Začni s externím odběrem. Vlastní pekárna je další investice pro rostoucí síť.')}<h3 style="margin-top:24px">Pořídit další pekárnu</h3>${stores.length?`<div class="fields">${field('Město s vlastní kavárnou',`<select id="bakeryCity5">${[...new Set(stores.map(s=>loc(s.id).city))].map(c=>option(c,c)).join('')}</select>`)}</div><div class="cards">${Object.entries(BAKERY_TYPES5).map(([id,t])=>`<article class="food-plan-card5"><h3>${t.name}</h3><p>${money(t.cost)} · základní kapacita ${t.capacity} jednotek/den · ${t.staff} pekařů</p><p class="sub">Mzdy ${money(t.staff*6500)} + provoz ${money(t.upkeep)}/týden. Žádné suroviny v kupní ceně.</p><button class="soft" data-bakery-buy5="${id}" ${state.cash<t.cost||bs.length>=8?'disabled':''}>Pořídit pekárnu</button></article>`).join('')}</div>`:empty('Pekárnu pořídíš ve městě své vlastní kavárny.')}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Vlastní receptury jídla</h2><select id="foodRecipeSelect5" aria-label="Receptura jídla">${state.bakery5.recipes.map(x=>option(x.id,x.name,r.id)).join('')}</select></div><div class="fields">${field('Název vlastní receptury',`<input id="foodRecipeName5" maxlength="50" value="${esc(r.name)}">`)}${field('Základ',`<select id="foodRecipeBase5">${Object.entries(FOOD_BASES5).map(([id,x])=>option(id,x.name,r.base)).join('')}</select>`)}${field('Bohatost přísad / %',input('foodRichness5',r.richness,70,140,5))}</div><div id="foodRecipeQuote5">${foodRecipeQuoteUI5(r)}</div><div class="actions"><button class="primary" id="foodRecipeSave5">Upravit budoucí výrobu</button><button class="soft" id="foodRecipeNew5">Uložit jako novou recepturu</button></div><p class="sub">Bohatší receptura zvýší množství přísad, cenu, pracnost i kvalitu. Rozvoj je zdarma; nová verze platí pro další výrobu. Již dodané šarže uchovají svůj název, verzi, cenu, kvalitu a trvanlivost. Používaná receptura zachovává svou kategorii.</p></section>`;}
function foodDayLabel5(day){return 'T'+(Math.floor(day/7)+1)+' '+['Po','Út','St','Čt','Pá','So','Ne'][day%7];}
function foodRecipeQuoteUI5(r){return rows([['Verze',r.version],['Trvanlivost od výroby',r.life+' dnů'],['Pracnost kusu',number(r.work,2)+' jednotek'],['Kvalita receptury',number(r.quality,1)+' / 100'],['Suroviny a energie / kus',money(r.unitCost)],...Object.entries(r.ingredients).map(([k,q])=>[INGREDIENTS5[k].name,number(q*1000,1)+' g'])]);}
menuView=function(){const html=BAKERY_UI5.menuView(),s=state.stores.find(s=>s.id===menuStore);return `<div class="actions"><button class="soft" id="menuFood5">Denní odběr, receptury a pekárna</button></div>`+(s?.food5.enabled?'<p class="sub">Fyzické jídlo je účtované podle skutečně prodaných kusů. Paušální jídlo na hosta v provozním modelu je nulové; skutečnou cenu zásob a tržby najdeš v Jídle a reportu.</p>':'')+html;};
financeView=function(){return '<div class="actions"><button class="soft" data-goto="bakery">Jídlo, zásoby a výrobní náklady</button></div>'+BAKERY_UI5.financeView();};
performanceView=function(){const html=BAKERY_UI5.performanceView();return ['food','bakeries'].includes(reportKind5)?html.replace('Soupeři mají vlastní ceny a baristy. Pobočky platí kávu, mzdy, nájem a provoz; skutečné obsloužené návštěvy omezí kapacita. Výsledek firmy navíc zahrnuje obchod, centrálu a úroky; investice snižují hotovost zvlášť. Jejich šarže a individuální fronty se nesimulují.','Jídlo se účtuje podle čerstvých fyzických šarží. Report pekárny ukazuje koncový příspěvek výrobního řetězce; interní rozvoz nepřidává tržby. Oba reporty se nesčítají, protože sledují stejné jídlo.'):html;};
performanceDetail5=function(id){BAKERY_UI5.performanceDetail5(id);if(['food','bakeries'].includes(reportKind5)&&el('reportManage5'))el('reportManage5').onclick=()=>{if(reportKind5==='food')foodStore5=id;else selectedBakery5=id;el('modal').close();goto('bakery');};};
bind=function(){BAKERY_UI5.bind();const num=id=>Number(el(id).value);if(el('foodStore5'))el('foodStore5').onchange=()=>{foodStore5=el('foodStore5').value;render();};if(el('bakerySelect5'))el('bakerySelect5').onchange=()=>{selectedBakery5=el('bakerySelect5').value;render();};if(el('foodRecipeSelect5'))el('foodRecipeSelect5').onchange=()=>{selectedFoodRecipe5=el('foodRecipeSelect5').value;render();};if(el('foodPlanSave5'))el('foodPlanSave5').onclick=()=>act(()=>setFoodPlan5(foodStore5,{enabled:el('foodEnabled5').checked,source:el('foodSource5').value,budget:num('foodBudget5'),reserve:num('foodReserve5'),plan:Object.fromEntries(['pastry','sandwich'].map(cat=>[cat,{recipe:el('foodRecipe-'+cat+'5').value,qty:num('foodQty-'+cat+'5')}]))}),'Denní odběr uložen.');on('[data-food-menu5]',b=>act(()=>updateMenu(foodStore5,b.dataset.foodMenu5,{...state.stores.find(s=>s.id===foodStore5).menu[b.dataset.foodMenu5],enabled:b.checked}),'Nabídka uložena.'),'change');on('[data-food-price5]',b=>act(()=>updateMenu(foodStore5,b.dataset.foodPrice5,{...state.stores.find(s=>s.id===foodStore5).menu[b.dataset.foodPrice5],price:Number(b.value)}),'Cena jídla uložena.'),'change');if(el('bakerySave5'))el('bakerySave5').onclick=()=>{const data={staff:num('bakeryStaff5'),shifts:num('bakeryShifts5'),budget:num('bakeryBudget5'),reserve:num('bakeryReserve5'),auto:el('bakeryAuto5').checked,maintenance:el('bakeryMaintenance5').checked},b=bakeryById5(selectedBakery5),cost=Math.max(0,data.staff-b.staff)*8000;confirmAction('Uložit provoz pekárny?',money(cost)+' za nové pekaře. Tým '+data.staff+' × 6 500 Kč/týden, směny '+data.shifts+'.',()=>setBakery5(b.id,data));};on('[data-bakery-buy5]',b=>{const type=b.dataset.bakeryBuy5,city=el('bakeryCity5').value;confirmAction('Pořídit vlastní pekárnu?',esc(BAKERY_TYPES5[type].name)+' · '+esc(city)+' · '+money(BAKERY_TYPES5[type].cost)+'. Tým a provoz se platí každý týden.',()=>{const b=buyBakery5(type,city);selectedBakery5=b.id;},'Koupit pekárnu');});if(el('bakeryService5'))el('bakeryService5').onclick=()=>confirmAction('Servis výrobního zařízení?',money(bakeryById5(selectedBakery5).cost*.04)+' za obnovení stavu na 100 %.',()=>serviceBakery5(selectedBakery5));on('[data-bakery-hire5]',b=>confirmAction('Přijmout vedoucího pekárny?',money(Math.max(4000,12000-state.departments.hr*1500))+' nábor; smluvní mzda každý týden.',()=>hireCandidate(selectedBakery5,b.dataset.bakeryHire5,'bakery')));if(el('bakeryFire5'))el('bakeryFire5').onclick=()=>confirmAction('Odvolat vedoucího pekárny?','Bez dalšího poplatku; zkušenosti zůstanou na trhu práce.',()=>fire(selectedBakery5,'bakery'));if(el('foodRawBuy5'))el('foodRawBuy5').onclick=()=>{try{const ingredient=el('foodRawIngredient5').value,kg=num('foodRawKg5'),q=rawFoodQuote5(selectedBakery5,ingredient,kg);confirmAction('Nakoupit surovinu?',esc(INGREDIENTS5[ingredient].name)+' · '+kg+' kg · '+money(q.cost)+'. Platba do zásob, ne nový provozní náklad. Trvanlivost '+INGREDIENTS5[ingredient].life+' dnů.',()=>buyFoodRaw5(selectedBakery5,ingredient,kg));}catch(e){toast(e.message);}};const recipeData=()=>({name:el('foodRecipeName5').value,base:el('foodRecipeBase5').value,richness:num('foodRichness5')});for(const id of ['foodRecipeName5','foodRecipeBase5','foodRichness5'])if(el(id))el(id).oninput=()=>{const data=recipeData();if(Number.isFinite(data.richness)&&data.richness>=70&&data.richness<=140)el('foodRecipeQuote5').innerHTML=foodRecipeQuoteUI5(foodRecipeDetails5({...data,version:foodRecipe5(selectedFoodRecipe5).version+1}));};if(el('foodRecipeSave5'))el('foodRecipeSave5').onclick=()=>act(()=>saveFoodRecipe5(selectedFoodRecipe5,recipeData()),'Nová verze platí pro budoucí šarže.');if(el('foodRecipeNew5'))el('foodRecipeNew5').onclick=()=>act(()=>{saveFoodRecipe5(null,recipeData());selectedFoodRecipe5=state.bakery5.recipes.at(-1).id;},'Vlastní receptura vytvořena.');if(el('menuFood5'))el('menuFood5').onclick=()=>{foodStore5=menuStore;goto('bakery');};on('[data-food-report5]',b=>{reportKind5=b.dataset.foodReport5;goto('performance');});if(el('foodForecast5'))el('foodForecast5').onclick=()=>{try{const f=bakeryForecast5(4);show(`<h2>Výhled celého provozu · 4 týdny</h2><p class="sub">Kopie skutečné firmy se současným odběrem, výrobou, konkurencí a událostmi. Budoucí ruční změny nejsou zahrnuté. Nejde o záruku výsledku.</p>${rows([['Výsledek celé firmy',money(f.profit)],['Hotovost na konci',money(f.cash)],['Jídlo skutečně prodané v kopii',f.sold+' kusů']])}<div class="table-scroll"><table class="data"><thead><tr><th>Týden</th><th>Výsledek firmy</th><th>Jídlo / tržby</th><th>Nákupy zásob</th><th>Odpis</th></tr></thead><tbody>${f.rows.map(r=>`<tr><td>${r.week}</td><td>${money(r.profit)}</td><td>${money(r.revenue)}</td><td>${money(r.purchases)}</td><td>${money(r.waste)}</td></tr>`).join('')}</tbody></table></div>${f.over?'<p class="bad">Firma ve výhledu ukončí činnost.</p>':''}`);}catch(e){toast(e.message);}};};
help=function(){BAKERY_UI5.help();const p=document.createElement('p');p.textContent='Edice 05.14: Jídlo & vlastní pekárna. Zapni fyzický odběr v konkrétní kavárně a vybav ji troubou nebo kuchyní. Začni externím rozvozem, potom pořiď pekárnu ve městě vlastní kavárny. Pekárna vyrábí podle denních odběrů, týmu, směn, surovin, mandátu a rezervy. Receptury mají vlastní náklady, kvalitu, pracnost a trvanlivost 1–3 dnů; změny platí pro budoucí šarže. Denní prodej omezuje počet skutečně obsloužených hostů a čerstvé zásoby. Interní rozvoz nevytváří další tržby. Report jídla a pekárny sleduje stejné zboží z různých pohledů; nesčítej je. Výhled simuluje kopii celé firmy. Stará uložená hra zachovává dosavadní zjednodušený prodej jídla do ručního zapnutí fyzického odběru.';el('modalContent').append(p);};el('help').onclick=help;render();
